 */
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@/registry/bejamas/ui/avatar";

interface TeamMember {
  id: string;
  name: string;
  role: string;
  avatar: string;
}

interface Props {
  class?: string;
  heading?: string;
  subheading?: string;
  description?: string;
  members?: TeamMember[];
}

const {
  class: className = "",
  heading = "Team",
  description = "Our diverse team of experts brings together decades of experience in design, engineering, and product development.",
  members = [
    {
      id: "member-1",
      name: "Sarah Chen",
      role: "CEO & Founder",
      avatar:
        "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/avatar-1.webp",
    },
    {
      id: "member-2",
      name: "Marcus Rodriguez",
      role: "CTO",
      avatar:
        "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/avatar-2.webp",
    },
    {
      id: "member-3",
      name: "Emily Watson",
      role: "Head of Design",
      avatar:
        "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/avatar-3.webp",
    },
    {
      id: "member-4",
      name: "David Kim",
      role: "Lead Engineer",
      avatar:
        "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/avatar-4.webp",
    },
    {
      id: "member-5",
      name: "Lisa Thompson",
      role: "Product Manager",
      avatar:
        "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/avatar-5.webp",
    },
    {
      id: "member-6",
      name: "Alex Johnson",
      role: "UX Designer",
      avatar:
        "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/avatar-6.webp",
    },
  ],
} = Astro.props;
---

<section class:list={["py-32", className]}>
  <div class="mx-auto w-full px-8 sm:max-w-[640px] md:max-w-[768px] lg:max-w-[1024px] xl:max-w-[1280px] 2xl:max-w-[1536px] flex flex-col items-center text-center">
    <h2 class="my-6 text-pretty text-2xl font-bold lg:text-4xl">{heading}</h2>
    <p class="text-muted-foreground mb-8 max-w-3xl lg:text-xl">{description}</p>
  </div>
  <div class="mx-auto w-full px-8 sm:max-w-[640px] md:max-w-[768px] lg:max-w-[1024px] xl:max-w-[1280px] 2xl:max-w-[1536px] mt-16 grid gap-x-8 gap-y-16 md:grid-cols-2 lg:grid-cols-3">
    {members.map((member) => (
      <div class="flex flex-col items-center">
        <Avatar class="mb-4 size-20 border md:mb-5 lg:size-24">
          <AvatarImage src={member.avatar} alt="" />
          <AvatarFallback>{member.name}</AvatarFallback>
        </Avatar>
        <p class="text-center font-medium">{member.name}</p>
        <p class="text-muted-foreground text-center">{member.role}</p>
      </div>
    ))}
  </div>
</section>
